function [r] = ocean_mod(x, y)
%OCEAN_MOD  Octave's mod(x, y) for finite doubles as doodson takes it: x - floor(x/y) y, 0 when y is not whole and x/y is within
%   one relative eps of a whole number, the result with the sign of y.
%   x: real[1] (passed a plain number)
%   y: real[1] (passed a plain number)
%   returns r: real[1] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    r = 0;
    if (y == 0)
        r = x;
    else
        q = (x / y);
        ny = floor((y + 0.5));
        nq = floor((q + 0.5));
        if ((ny ~= y) && (asils.pc.fabs(((q - nq) / nq)) < 2.220446049250313e-16))
            r = 0;
        else
            r = (x - (y * floor(q)));
        end
        if (((x ~= y) && (r ~= 0)) && ((r < 0) ~= (y < 0)))
            r = (r + y);
        end
    end
end
